#!/usr/bin/env python3
"""Update the reviewed homepage, CSS and new portrait; never restart services."""
import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import zlib

BASE = Path('/opt/outdoor-fit/production')
WEB = BASE / 'releases/public-website-20260928-v1/website'
CADDY = 'outdoor-fit-production-caddy-1'
ASSET_NAME = 'assets/cindy-li.webp'
PROFESSOR = b'https://www.polyu.edu.hk/comp/people/academic-staff/prof-ng-hiu-fung-peter/'
# Reviewed final files are embedded below; only known v1/profile-patched hashes are accepted.
PARTNER_URLS = ['https://www.polyu.edu.hk/tc/about-polyu/', 'https://www.twc.edu.hk/tc/twc/About_TWC/vision_and_mission', 'https://www.feinberg.northwestern.edu/about/index.html', 'https://www.hkcc-polyu.edu.hk/tc/about-hkcc/college-overview/index.html', 'https://www.hkpfa.org.hk/CP/pG/2/1/6']
PAYLOADS = {'index.html': {'acceptedSha256': ['864de7e4e48faefd7fc3da9c8bfe6ba132bcae854e0f51c081c3071c89c30cd1', '0b8481adcca546be80e1068b9d7f5762ab56dc95e037f3e4713b1f924d63c3ef', '845f418f3d451070a97b3049038e234ab5a4b4caf3b8f13928552e26c22ddf86'], 'sha256': '88b74e3f5832c7d3e998e36b97e4b656276e7ebab10a4d543a8ce47bac1b0bbb', 'data': ''}, 'site.css': {'acceptedSha256': ['aa887615fdfddfd3487228f8def21817d47914bb088652ff4feb14f4913cbf57', 'bb0dbbabebf41bfe4983d317daac2daabee580fff0fd2c2b73fb142be0629f22', '9467df627ec0d08bed6842d41dedf5e3c90ac0bf8b5835a6b37c0e65b59ba884'], 'sha256': '9467df627ec0d08bed6842d41dedf5e3c90ac0bf8b5835a6b37c0e65b59ba884', 'data': ''}, 'assets/cindy-li.webp': {'acceptedSha256': [], 'sha256': '15a250426789a3e7429c5ff07614c57493edb4ad4aac24ab397a4c5f03ec8161', 'data': ''}}


def require(ok, code):
    if not ok:
        raise RuntimeError(code)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def run(args):
    result = subprocess.run(args, capture_output=True, timeout=20)
    require(result.returncode == 0, 'LINKS_COMMAND_FAILED')
    return result.stdout


def decode_payloads():
    require(isinstance(ASSET_NAME, str) and ASSET_NAME.startswith('assets/')
            and Path(ASSET_NAME).name == ASSET_NAME[7:] and ASSET_NAME.endswith('.webp')
            and set(PAYLOADS) == {'index.html', 'site.css', ASSET_NAME} and len(PARTNER_URLS) == 5,
            'LINKS_PAYLOAD_INCOMPLETE')
    result = {}
    for name, item in PAYLOADS.items():
        data = zlib.decompress(base64.b64decode(item['data'], validate=True))
        require(sha(data) == item['sha256'], 'LINKS_PAYLOAD_HASH_MISMATCH')
        result[name] = data
    page = result['index.html']
    require(page.count(b'href="' + PROFESSOR + b'"') == 2, 'LINKS_PROFESSOR_COUNT_INVALID')
    for url in PARTNER_URLS:
        require(page.count(('href="' + url + '"').encode()) == 1, 'LINKS_PARTNER_COUNT_INVALID')
    require(page.count(('src="/' + ASSET_NAME + '"').encode()) == 1
            and '李欣迪'.encode() in page and '李欣迪教授'.encode() not in page,
            'LINKS_NEW_COLLABORATOR_INVALID')
    return result


def atomic_write(path, data, metadata, restore_time=False):
    descriptor, temporary = tempfile.mkstemp(prefix='.website-links-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chown(temporary, metadata.st_uid, metadata.st_gid)
        shutil.copystat(path, temporary, follow_symlinks=False)
        os.chmod(temporary, stat.S_IMODE(metadata.st_mode))
        os.utime(temporary, ns=(metadata.st_atime_ns,
                               metadata.st_mtime_ns if restore_time else time.time_ns()))
        os.replace(temporary, path)
        if hasattr(os, 'O_DIRECTORY'):
            directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def create_asset(path, data, metadata):
    """Publish an absent file without ever replacing a concurrent/unknown file."""
    descriptor, temporary = tempfile.mkstemp(prefix='.website-portrait-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chown(temporary, metadata.st_uid, metadata.st_gid)
        os.chmod(temporary, 0o644)
        # A hard link creates the final name atomically and refuses an existing name.
        os.link(temporary, path)
        info = path.stat()
        return info.st_dev, info.st_ino
    finally:
        try:
            os.unlink(temporary)
        except OSError:
            pass


def update(web, backup_parent, verify):
    desired = decode_payloads()
    before, metadata = {}, {}
    for name in desired:
        path = web / name
        require(not path.is_symlink() and path.parent.is_dir()
                and path.parent.resolve() in {web.resolve(), (web / 'assets').resolve()}
                and not path.parent.is_symlink(), 'LINKS_FILE_PATH_INVALID')
        if name == ASSET_NAME and not path.exists():
            before[name], metadata[name] = None, None
            continue
        require(path.is_file() and not path.is_symlink() and path.stat().st_nlink == 1,
                'LINKS_FILE_NOT_REGULAR')
        metadata[name] = path.stat()
        before[name] = path.read_bytes()
        require(sha(before[name]) in PAYLOADS[name]['acceptedSha256'] + [PAYLOADS[name]['sha256']],
                'LINKS_UNKNOWN_EXISTING_FILE_' + name.replace('.', '_').upper())
    changes = [name for name in [ASSET_NAME, 'site.css', 'index.html'] if before[name] != desired[name]]
    if not changes:
        verify(desired)
        print('LINKS_UPDATE=ALREADY_CURRENT')
        return
    require(backup_parent.is_dir() and not backup_parent.is_symlink(), 'LINKS_BACKUP_PARENT_INVALID')
    backup = Path(tempfile.mkdtemp(prefix='website-links-20260928-', dir=backup_parent))
    backup.chmod(0o700)
    for name, data in before.items():
        saved = backup / (Path(name).name + '.before')
        if data is None:
            saved = backup / 'portrait-originally-absent.txt'
            data = ASSET_NAME.encode() + b'\n'
        saved.write_bytes(data)
        saved.chmod(0o600)
    print('LINKS_BACKUP_DIR=' + str(backup), flush=True)
    touched, created = [], {}
    try:
        for name in changes:
            path = web / name
            if before[name] is None:
                created[name] = create_asset(path, desired[name], metadata['index.html'])
                touched.append(name)
                continue
            require(path.read_bytes() == before[name] and path.stat().st_ino == metadata[name].st_ino,
                    'LINKS_CONCURRENT_EDIT_DETECTED')
            touched.append(name)
            atomic_write(path, desired[name], metadata[name])
        verify(desired)
    except BaseException:
        restored = True
        for name in reversed(touched):
            path = web / name
            try:
                current = path.read_bytes()
                if before[name] is None:
                    info = path.stat()
                    if (current == desired[name] and not path.is_symlink()
                            and (info.st_dev, info.st_ino) == created[name]):
                        path.unlink()
                    else:
                        restored = False
                elif current == desired[name]:
                    atomic_write(path, before[name], metadata[name], restore_time=True)
                elif current != before[name]:
                    restored = False
            except BaseException:
                restored = False
        print('LINKS_ROLLBACK=' + ('COMPLETE' if restored else 'NEEDS_REVIEW_NO_OVERWRITE'), flush=True)
        raise
    print('LINKS_UPDATED_FILES=' + ','.join(changes)
          + '\nLINKS_PROFESSOR_HREFS=2\nLINKS_PARTNER_HREFS=5\nLINKS_SERVED_FILES=PASS\nLINKS_UPDATE=PASS',
          flush=True)


def main():
    import fcntl
    os.umask(0o077)
    require(os.geteuid() == 0, 'LINKS_ROOT_REQUIRED')
    require(WEB.is_dir() and WEB.resolve() == WEB, 'LINKS_RELEASE_PATH_CHANGED')
    live = json.loads(run(['docker', 'inspect', CADDY]))[0]
    require(live['State']['Running'], 'LINKS_CADDY_NOT_RUNNING')
    mounts = [item for item in live['Mounts'] if item['Destination'] == '/srv/website']
    require(len(mounts) == 1 and mounts[0]['Type'] == 'bind' and mounts[0]['Source'] == str(WEB)
            and mounts[0]['RW'] is False, 'LINKS_WEBSITE_MOUNT_CHANGED')

    def verify(expected):
        for name, data in expected.items():
            resource = '/' if name == 'index.html' else '/' + name
            served = run(['docker', 'exec', CADDY, 'wget', '-q', '-O', '-',
                          '--header=Host: outdoorfit.hk', 'http://127.0.0.1:8099' + resource])
            require(sha(served) == sha(data), 'LINKS_SERVED_FILE_MISMATCH')

    with (BASE / '.public-website.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        update(WEB, BASE / '.update-state', verify)


if __name__ == '__main__':
    try:
        main()
    except RuntimeError as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
    except (Exception, KeyboardInterrupt):
        print('LINKS_UPDATE_FAILED_NO_SECRETS_LOGGED', file=sys.stderr)
        sys.exit(1)
